-- The schema of an Immuch360 Desktop database that every start of desktop builds 6 to 8 refused with
-- "duplicate column name: group_date": the tables and indexes of schema 35, user_version 34. A build at schema 35
-- migrated it, then a build at schema 34 opened it, and drift wrote that build's version to user_version while the
-- columns of 35 stayed. The CREATE statements are those of sqlite_master of the database found on a PC, in their order,
-- without any row. Used by migration_rerun_test.dart and by the Windows job of immuch360-desktop.yml, which starts the
-- release build on it.
CREATE TABLE "user_entity" ("id" TEXT NOT NULL, "name" TEXT NOT NULL, "email" TEXT NOT NULL, "has_profile_image" INTEGER NOT NULL DEFAULT 0 CHECK ("has_profile_image" IN (0, 1)), "profile_changed_at" TEXT NOT NULL DEFAULT (CURRENT_TIMESTAMP), "avatar_color" INTEGER NOT NULL DEFAULT 0, PRIMARY KEY ("id")) WITHOUT ROWID, STRICT;
CREATE TABLE "remote_asset_entity" ("name" TEXT NOT NULL, "type" INTEGER NOT NULL, "created_at" TEXT NOT NULL DEFAULT (CURRENT_TIMESTAMP), "updated_at" TEXT NOT NULL DEFAULT (CURRENT_TIMESTAMP), "width" INTEGER NULL, "height" INTEGER NULL, "duration_ms" INTEGER NULL, "id" TEXT NOT NULL, "checksum" TEXT NOT NULL, "is_favorite" INTEGER NOT NULL DEFAULT 0 CHECK ("is_favorite" IN (0, 1)), "owner_id" TEXT NOT NULL REFERENCES user_entity (id) ON DELETE CASCADE, "local_date_time" TEXT NULL, "thumb_hash" TEXT NULL, "deleted_at" TEXT NULL, "uploaded_at" TEXT NULL, "live_photo_video_id" TEXT NULL, "visibility" INTEGER NOT NULL, "stack_id" TEXT NULL, "library_id" TEXT NULL, "is_edited" INTEGER NOT NULL DEFAULT 0 CHECK ("is_edited" IN (0, 1)), "group_date" TEXT NULL, PRIMARY KEY ("id")) WITHOUT ROWID, STRICT;
CREATE TABLE "stack_entity" ("id" TEXT NOT NULL, "created_at" TEXT NOT NULL DEFAULT (CURRENT_TIMESTAMP), "updated_at" TEXT NOT NULL DEFAULT (CURRENT_TIMESTAMP), "owner_id" TEXT NOT NULL REFERENCES user_entity (id) ON DELETE CASCADE, "primary_asset_id" TEXT NOT NULL, PRIMARY KEY ("id")) WITHOUT ROWID, STRICT;
CREATE TABLE "local_asset_entity" ("name" TEXT NOT NULL, "type" INTEGER NOT NULL, "created_at" TEXT NOT NULL DEFAULT (CURRENT_TIMESTAMP), "updated_at" TEXT NOT NULL DEFAULT (CURRENT_TIMESTAMP), "width" INTEGER NULL, "height" INTEGER NULL, "duration_ms" INTEGER NULL, "id" TEXT NOT NULL, "checksum" TEXT NULL, "is_favorite" INTEGER NOT NULL DEFAULT 0 CHECK ("is_favorite" IN (0, 1)), "orientation" INTEGER NOT NULL DEFAULT 0, "i_cloud_id" TEXT NULL, "adjustment_time" TEXT NULL, "latitude" REAL NULL, "longitude" REAL NULL, "playback_style" INTEGER NOT NULL DEFAULT 0, "previous_checksum" TEXT NULL, "group_date" TEXT NULL, PRIMARY KEY ("id")) WITHOUT ROWID, STRICT;
CREATE TABLE "remote_album_entity" ("id" TEXT NOT NULL, "name" TEXT NOT NULL, "description" TEXT NOT NULL DEFAULT '', "created_at" TEXT NOT NULL DEFAULT (CURRENT_TIMESTAMP), "updated_at" TEXT NOT NULL DEFAULT (CURRENT_TIMESTAMP), "thumbnail_asset_id" TEXT NULL REFERENCES remote_asset_entity (id) ON DELETE SET NULL, "is_activity_enabled" INTEGER NOT NULL DEFAULT 1 CHECK ("is_activity_enabled" IN (0, 1)), "order" INTEGER NOT NULL, PRIMARY KEY ("id")) WITHOUT ROWID, STRICT;
CREATE TABLE "local_album_entity" ("id" TEXT NOT NULL, "name" TEXT NOT NULL, "updated_at" TEXT NOT NULL DEFAULT (CURRENT_TIMESTAMP), "backup_selection" INTEGER NOT NULL, "is_ios_shared_album" INTEGER NOT NULL DEFAULT 0 CHECK ("is_ios_shared_album" IN (0, 1)), "linked_remote_album_id" TEXT NULL REFERENCES remote_album_entity (id) ON DELETE SET NULL, "marker" INTEGER NULL CHECK ("marker" IN (0, 1)), PRIMARY KEY ("id")) WITHOUT ROWID, STRICT;
CREATE TABLE "local_album_asset_entity" ("asset_id" TEXT NOT NULL REFERENCES local_asset_entity (id) ON DELETE CASCADE, "album_id" TEXT NOT NULL REFERENCES local_album_entity (id) ON DELETE CASCADE, "marker" INTEGER NULL CHECK ("marker" IN (0, 1)), PRIMARY KEY ("asset_id", "album_id")) WITHOUT ROWID, STRICT;
CREATE INDEX idx_local_album_asset_album_asset ON local_album_asset_entity (album_id, asset_id);
CREATE INDEX idx_local_asset_checksum ON local_asset_entity (checksum);
CREATE INDEX idx_local_asset_cloud_id ON local_asset_entity (i_cloud_id);
CREATE INDEX idx_local_asset_created_at ON local_asset_entity (created_at);
CREATE INDEX idx_stack_primary_asset_id ON stack_entity (primary_asset_id);
CREATE UNIQUE INDEX UQ_remote_assets_owner_checksum ON remote_asset_entity (owner_id, checksum) WHERE(library_id IS NULL);
CREATE UNIQUE INDEX UQ_remote_assets_owner_library_checksum ON remote_asset_entity (owner_id, library_id, checksum) WHERE(library_id IS NOT NULL);
CREATE INDEX idx_remote_asset_checksum ON remote_asset_entity (checksum);
CREATE INDEX idx_remote_asset_stack_id ON remote_asset_entity (stack_id);
CREATE INDEX idx_remote_asset_owner_visibility_deleted_created ON remote_asset_entity (owner_id, visibility, deleted_at, created_at DESC);
CREATE INDEX idx_remote_asset_uploaded ON remote_asset_entity (uploaded_at);
CREATE TABLE "auth_user_entity" ("id" TEXT NOT NULL, "name" TEXT NOT NULL, "email" TEXT NOT NULL, "is_admin" INTEGER NOT NULL DEFAULT 0 CHECK ("is_admin" IN (0, 1)), "has_profile_image" INTEGER NOT NULL DEFAULT 0 CHECK ("has_profile_image" IN (0, 1)), "profile_changed_at" TEXT NOT NULL DEFAULT (CURRENT_TIMESTAMP), "avatar_color" INTEGER NOT NULL, "quota_size_in_bytes" INTEGER NOT NULL DEFAULT 0, "quota_usage_in_bytes" INTEGER NOT NULL DEFAULT 0, "pin_code" TEXT NULL, PRIMARY KEY ("id")) WITHOUT ROWID, STRICT;
CREATE TABLE "user_metadata_entity" ("user_id" TEXT NOT NULL REFERENCES user_entity (id) ON DELETE CASCADE, "key" INTEGER NOT NULL, "value" BLOB NOT NULL, PRIMARY KEY ("user_id", "key")) WITHOUT ROWID, STRICT;
CREATE TABLE "partner_entity" ("shared_by_id" TEXT NOT NULL REFERENCES user_entity (id) ON DELETE CASCADE, "shared_with_id" TEXT NOT NULL REFERENCES user_entity (id) ON DELETE CASCADE, "in_timeline" INTEGER NOT NULL DEFAULT 0 CHECK ("in_timeline" IN (0, 1)), PRIMARY KEY ("shared_by_id", "shared_with_id")) WITHOUT ROWID, STRICT;
CREATE TABLE "remote_exif_entity" ("asset_id" TEXT NOT NULL REFERENCES remote_asset_entity (id) ON DELETE CASCADE, "city" TEXT NULL, "state" TEXT NULL, "country" TEXT NULL, "date_time_original" TEXT NULL, "description" TEXT NULL, "height" INTEGER NULL, "width" INTEGER NULL, "exposure_time" TEXT NULL, "f_number" REAL NULL, "file_size" INTEGER NULL, "focal_length" REAL NULL, "latitude" REAL NULL, "longitude" REAL NULL, "iso" INTEGER NULL, "make" TEXT NULL, "model" TEXT NULL, "lens" TEXT NULL, "orientation" TEXT NULL, "time_zone" TEXT NULL, "rating" INTEGER NULL, "projection_type" TEXT NULL, PRIMARY KEY ("asset_id")) WITHOUT ROWID, STRICT;
CREATE TABLE "remote_album_asset_entity" ("asset_id" TEXT NOT NULL REFERENCES remote_asset_entity (id) ON DELETE CASCADE, "album_id" TEXT NOT NULL REFERENCES remote_album_entity (id) ON DELETE CASCADE, PRIMARY KEY ("asset_id", "album_id")) WITHOUT ROWID, STRICT;
CREATE TABLE "remote_album_user_entity" ("album_id" TEXT NOT NULL REFERENCES remote_album_entity (id) ON DELETE CASCADE, "user_id" TEXT NOT NULL REFERENCES user_entity (id) ON DELETE CASCADE, "role" INTEGER NOT NULL, PRIMARY KEY ("album_id", "user_id")) WITHOUT ROWID, STRICT;
CREATE TABLE "remote_asset_cloud_id_entity" ("asset_id" TEXT NOT NULL REFERENCES remote_asset_entity (id) ON DELETE CASCADE, "cloud_id" TEXT NULL, "created_at" TEXT NULL, "adjustment_time" TEXT NULL, "latitude" REAL NULL, "longitude" REAL NULL, PRIMARY KEY ("asset_id")) WITHOUT ROWID, STRICT;
CREATE TABLE "memory_entity" ("id" TEXT NOT NULL, "created_at" TEXT NOT NULL DEFAULT (CURRENT_TIMESTAMP), "updated_at" TEXT NOT NULL DEFAULT (CURRENT_TIMESTAMP), "deleted_at" TEXT NULL, "owner_id" TEXT NOT NULL REFERENCES user_entity (id) ON DELETE CASCADE, "type" INTEGER NOT NULL, "data" TEXT NOT NULL, "is_saved" INTEGER NOT NULL DEFAULT 0 CHECK ("is_saved" IN (0, 1)), "memory_at" TEXT NOT NULL, "seen_at" TEXT NULL, "show_at" TEXT NULL, "hide_at" TEXT NULL, PRIMARY KEY ("id")) WITHOUT ROWID, STRICT;
CREATE TABLE "memory_asset_entity" ("asset_id" TEXT NOT NULL REFERENCES remote_asset_entity (id) ON DELETE CASCADE, "memory_id" TEXT NOT NULL REFERENCES memory_entity (id) ON DELETE CASCADE, PRIMARY KEY ("asset_id", "memory_id")) WITHOUT ROWID, STRICT;
CREATE TABLE "person_entity" ("id" TEXT NOT NULL, "created_at" TEXT NOT NULL DEFAULT (CURRENT_TIMESTAMP), "updated_at" TEXT NOT NULL DEFAULT (CURRENT_TIMESTAMP), "owner_id" TEXT NOT NULL REFERENCES user_entity (id) ON DELETE CASCADE, "name" TEXT NOT NULL, "face_asset_id" TEXT NULL, "is_favorite" INTEGER NOT NULL CHECK ("is_favorite" IN (0, 1)), "is_hidden" INTEGER NOT NULL CHECK ("is_hidden" IN (0, 1)), "color" TEXT NULL, "birth_date" TEXT NULL, PRIMARY KEY ("id")) WITHOUT ROWID, STRICT;
CREATE TABLE "asset_face_entity" ("id" TEXT NOT NULL, "asset_id" TEXT NOT NULL, "person_id" TEXT NULL, "image_width" INTEGER NOT NULL, "image_height" INTEGER NOT NULL, "bounding_box_x1" INTEGER NOT NULL, "bounding_box_y1" INTEGER NOT NULL, "bounding_box_x2" INTEGER NOT NULL, "bounding_box_y2" INTEGER NOT NULL, "source_type" TEXT NOT NULL, "is_visible" INTEGER NOT NULL DEFAULT 1 CHECK ("is_visible" IN (0, 1)), "deleted_at" TEXT NULL, PRIMARY KEY ("id")) WITHOUT ROWID, STRICT;
CREATE TABLE "store_entity" ("id" INTEGER NOT NULL, "string_value" TEXT NULL, "int_value" INTEGER NULL, PRIMARY KEY ("id")) WITHOUT ROWID, STRICT;
CREATE TABLE "trashed_local_asset_entity" ("name" TEXT NOT NULL, "type" INTEGER NOT NULL, "created_at" TEXT NOT NULL DEFAULT (CURRENT_TIMESTAMP), "updated_at" TEXT NOT NULL DEFAULT (CURRENT_TIMESTAMP), "width" INTEGER NULL, "height" INTEGER NULL, "duration_ms" INTEGER NULL, "id" TEXT NOT NULL, "album_id" TEXT NOT NULL, "checksum" TEXT NULL, "is_favorite" INTEGER NOT NULL DEFAULT 0 CHECK ("is_favorite" IN (0, 1)), "orientation" INTEGER NOT NULL DEFAULT 0, "source" INTEGER NOT NULL, "playback_style" INTEGER NOT NULL DEFAULT 0, PRIMARY KEY ("id", "album_id")) WITHOUT ROWID, STRICT;
CREATE TABLE "asset_edit_entity" ("id" TEXT NOT NULL, "asset_id" TEXT NOT NULL REFERENCES remote_asset_entity (id) ON DELETE CASCADE, "action" INTEGER NOT NULL, "parameters" BLOB NOT NULL, "sequence" INTEGER NOT NULL, PRIMARY KEY ("id")) WITHOUT ROWID, STRICT;
CREATE TABLE "settings" ("key" TEXT NOT NULL, "value" TEXT NULL, "updated_at" TEXT NOT NULL DEFAULT (CURRENT_TIMESTAMP), PRIMARY KEY ("key")) WITHOUT ROWID, STRICT;
CREATE TABLE "asset_ocr_entity" ("id" TEXT NOT NULL, "asset_id" TEXT NOT NULL REFERENCES remote_asset_entity (id) ON DELETE CASCADE, "x1" REAL NOT NULL, "y1" REAL NOT NULL, "x2" REAL NOT NULL, "y2" REAL NOT NULL, "x3" REAL NOT NULL, "y3" REAL NOT NULL, "x4" REAL NOT NULL, "y4" REAL NOT NULL, "box_score" REAL NOT NULL, "text_score" REAL NOT NULL, "recognized_text" TEXT NOT NULL, "is_visible" INTEGER NOT NULL DEFAULT 1 CHECK ("is_visible" IN (0, 1)), PRIMARY KEY ("id")) WITHOUT ROWID, STRICT;
CREATE INDEX idx_partner_shared_with_id ON partner_entity (shared_with_id);
CREATE INDEX idx_lat_lng ON remote_exif_entity (latitude, longitude);
CREATE INDEX idx_remote_exif_city ON remote_exif_entity (city) WHERE city IS NOT NULL;
CREATE INDEX idx_remote_album_asset_album_asset ON remote_album_asset_entity (album_id, asset_id);
CREATE INDEX idx_remote_asset_cloud_id ON remote_asset_cloud_id_entity (cloud_id);
CREATE INDEX idx_person_owner_id ON person_entity (owner_id);
CREATE INDEX idx_asset_face_person_id ON asset_face_entity (person_id);
CREATE INDEX idx_asset_face_asset_id ON asset_face_entity (asset_id);
CREATE INDEX idx_asset_face_visible_person ON asset_face_entity (person_id, asset_id) WHERE is_visible = 1 AND deleted_at IS NULL;
CREATE INDEX idx_trashed_local_asset_checksum ON trashed_local_asset_entity (checksum);
CREATE INDEX idx_trashed_local_asset_album ON trashed_local_asset_entity (album_id);
CREATE INDEX idx_asset_edit_asset_id ON asset_edit_entity (asset_id);
CREATE INDEX idx_asset_ocr_asset_id ON asset_ocr_entity (asset_id);
CREATE INDEX idx_remote_asset_group ON remote_asset_entity (owner_id, visibility, deleted_at, group_date DESC, created_at DESC);
CREATE INDEX idx_local_asset_group ON local_asset_entity (group_date DESC, created_at DESC);
PRAGMA user_version = 34;
